func ptrSSOConfig(p unsafe.Pointer, c int32) any {
	r := (*sso.SSOConfig)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 2:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 3:
		return &r.Name
	case 4:
		return (*string)(unsafe.Pointer(&r.Provider))
	case 5:
		return (*string)(unsafe.Pointer(&r.Protocol))
	case 6:
		return &r.Enabled
	case 7:
		return &r.EnforceSSO
	case 8:
		return &r.AutoProvision
	case 9:
		return &r.DefaultRole
	case 10:
		return &r.AllowedDomains
	case 11:
		return &r.AttributeMap
	case 12:
		return &r.OIDCIssuerURL
	case 13:
		return &r.OIDCClientID
	case 14:
		return &r.OIDCClientSecret
	case 15:
		return &r.OIDCRedirectURL
	case 16:
		return &r.OIDCScopes
	case 17:
		return &r.Version
	case 18:
		return &r.CreatedAt
	case 19:
		return &r.UpdatedAt
	}
	return nil
}

func valueSSOConfig(p unsafe.Pointer, c int32) any {
	r := (*sso.SSOConfig)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.OrganizationID)
	case 2:
		return string(r.BusinessUnitID)
	case 3:
		return r.Name
	case 4:
		return string(r.Provider)
	case 5:
		return string(r.Protocol)
	case 6:
		return r.Enabled
	case 7:
		return r.EnforceSSO
	case 8:
		return r.AutoProvision
	case 9:
		if r.DefaultRole == "" {
			return nil
		}
		return r.DefaultRole
	case 10:
		if r.AllowedDomains == nil {
			return []string{}
		}
		return r.AllowedDomains
	case 11:
		if r.AttributeMap == nil {
			return keel.EmptyJSONObject
		}
		return r.AttributeMap
	case 12:
		return r.OIDCIssuerURL
	case 13:
		return r.OIDCClientID
	case 14:
		return r.OIDCClientSecret
	case 15:
		return r.OIDCRedirectURL
	case 16:
		if r.OIDCScopes == nil {
			return []string{}
		}
		return r.OIDCScopes
	case 17:
		return r.Version
	case 18:
		return r.CreatedAt
	case 19:
		return r.UpdatedAt
	}
	return nil
}

